# Setup-McpJson.ps1
# Creates .mcp.json in the current folder (run it from the Unreal project root) using the token
# generated by the EngineWire plugin in Saved\MCP\capability-token.
# The token is read and written to the file only. It is never printed.

$ErrorActionPreference = 'Stop'
$root      = (Get-Location).Path
$tokenFile = Join-Path $root 'Saved\MCP\capability-token'
$outFile   = Join-Path $root '.mcp.json'

if (-not (Test-Path (Join-Path $root 'PortalBuddy.uproject'))) {
    Write-Host "Run this from the PortalBuddy project folder (PortalBuddy.uproject not found in $root)." -ForegroundColor Red
    exit 1
}
if (-not (Test-Path $tokenFile)) {
    Write-Host "Token file not found: $tokenFile" -ForegroundColor Red
    Write-Host "Open the project in Unreal Engine first, with EngineWire's Native MCP server enabled (status bar shows MCP :3000)." -ForegroundColor Yellow
    exit 1
}

$token = (Get-Content $tokenFile -Raw).Trim()
if ([string]::IsNullOrWhiteSpace($token)) { Write-Host 'Token file is empty.' -ForegroundColor Red; exit 1 }

$json = @"
{
  "mcpServers": {
    "unreal-engine": {
      "type": "http",
      "url": "http://127.0.0.1:3000/mcp",
      "headers": { "X-MCP-Capability-Token": "$token" }
    }
  }
}
"@

# UTF-8 without BOM so the JSON parses everywhere
[System.IO.File]::WriteAllText($outFile, $json, (New-Object System.Text.UTF8Encoding($false)))
Write-Host "Wrote $outFile (token not displayed)." -ForegroundColor Green

# Make sure the secret file is ignored by git
$gi = Join-Path $root '.gitignore'
if ((Test-Path $gi) -and -not (Select-String -Path $gi -Pattern '^\.mcp\.json$' -Quiet)) {
    Write-Host 'WARNING: .mcp.json is NOT in .gitignore. Add it before any commit.' -ForegroundColor Yellow
}

Write-Host 'Reminder: loopback must bypass the university proxy ->  $env:NO_PROXY = "127.0.0.1,localhost,::1"' -ForegroundColor Cyan
